// bodies for the ray tracer (bots; remote players appended by main.js)
renderBodies() {
  const spheres = [], capsules = [];
  for (const b of this.bots) {
    if (!b.alive && b.deathT <= 0) continue;
    const sink = b.alive ? 0 : (1 - b.deathT / 0.6) * 1.6;
    const rig = characterRig(b.pos, b.yaw, false, b.tint, sink, b.walkPhase || 0, b.moving || 0);
